import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 21 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * earlier practice tests.
 */

// ─────────────────────── PRACTICE TEST 21 · R&W M1 (27) ──────────────────────
const T21_RW_M1: SatQuestion[] = [
  { id: "t21rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The lecturer's explanations were so ______ that even students new to the subject could follow each step without confusion.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["lucid", "convoluted", "tedious", "abrupt"], correct: 0, explanation: "The answer is \"lucid\" (A). The sentence says even brand-new students could \"follow each step without confusion,\" so the explanations must be exceptionally clear, which is what lucid means. (B) \"convoluted\" means twisted and hard to follow, the exact opposite of confusion-free. (C) \"tedious\" describes something boring and tiresome, which says nothing about whether it can be understood. (D) \"abrupt\" means sudden or curt, which would tend to hinder, not aid, easy step-by-step following." },
  { id: "t21rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of advisers ______ scheduled to release its recommendations next month.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "The answer is \"is\" (A). The grammatical subject is the singular collective noun \"committee\"; subject-verb agreement is set by that head noun, and the intervening prepositional phrase \"of advisers\" never controls the verb. (B) \"are\" is plural and wrongly agrees with the nearby \"advisers\" instead of \"committee.\" (C) \"have been\" is also plural and likewise mismatches the singular subject. (D) \"were\" is plural and additionally shifts to past tense, doubling the error." },
  { id: "t21rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Coral reefs host a quarter of all marine species despite covering less than one percent of the ocean floor, making them among the most biologically concentrated habitats on Earth.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Coral reefs support enormous biodiversity within a tiny area.", "Coral reefs cover most of the ocean floor.", "Most marine species avoid coral reefs.", "Coral reefs contain no marine life."], correct: 0, explanation: "The answer is (A). The text pairs two facts—reefs host \"a quarter of all marine species\" yet cover \"less than one percent of the ocean floor\"—which together mean enormous biodiversity packed into a tiny area, exactly what A states. (B) flatly contradicts \"less than one percent of the ocean floor.\" (C) contradicts the claim that reefs host a quarter of all marine species; species concentrate in reefs rather than avoiding them. (D) contradicts the same statistic by denying any marine life at all." },
  { id: "t21rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail was washed out by the storm. ______, the hikers turned back before reaching the summit.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Therefore", "However", "Likewise"], correct: 1, explanation: "The answer is \"Therefore\" (B). The washed-out trail is the cause and turning back is its logical effect, so a cause-and-effect transition is needed. (A) \"Nevertheless\" signals contrast, wrongly implying the hikers turned back in spite of the washout rather than because of it. (C) \"However\" likewise marks contradiction, which the cause-effect relationship does not contain. (D) \"Likewise\" signals similarity between two parallel ideas, but here the second sentence is a result, not a comparison." },
  { id: "t21rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit includes everything a beginner needs ______ paints, brushes, and a sturdy canvas.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needs, ", "needs: ", "needs; ", "needs "], correct: 1, explanation: "The answer is the colon, \"needs: \" (B). \"The kit includes everything a beginner needs\" is a complete independent clause, and a colon is the correct mark to introduce the list that then specifies that \"everything.\" (A) the comma is too weak to introduce an explanatory list following a full clause. (C) the semicolon must join two independent clauses, but \"paints, brushes, and a sturdy canvas\" is only a list, not a clause. (D) no punctuation runs the list directly into the clause with no signal that an enumeration follows." },
  { id: "t21rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The negotiator remained ______ throughout the tense talks, never once raising her voice or losing her composure.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unflappable", "frantic", "indifferent", "hostile"], correct: 0, explanation: "The answer is \"unflappable\" (A). The clause \"never once raising her voice or losing her composure\" defines someone who stays calm under pressure, which is precisely what unflappable means. (B) \"frantic\" means wildly agitated, the opposite of keeping composure. (C) \"indifferent\" means uncaring, which describes a lack of interest rather than the active self-control the sentence highlights. (D) \"hostile\" means aggressively unfriendly, contradicting a negotiator who never raises her voice." },
  { id: "t21rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is offered only to students who have completed at least two years of college and who maintain a grade-point average above 3.5.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A first-year student with a 3.8 average is ineligible for the scholarship.", "Any college student qualifies for the scholarship.", "The scholarship requires no minimum grade-point average.", "Graduate students alone may apply."], correct: 0, explanation: "Both conditions are required; a first-year student has not completed two years, so even a 3.8 average leaves them ineligible (A). B ignores both conditions, C contradicts the 3.5 requirement, and D adds a restriction the text never states." },
  { id: "t21rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum expanded its galleries last year. ______, it lengthened its weekend hours to welcome larger crowds.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Instead", "Otherwise"], correct: 1, explanation: "The answer is \"In addition\" (B). Lengthening weekend hours is a second, parallel expansion stacked onto the gallery expansion, so an additive transition fits. (A) \"However\" signals contrast, but the two improvements agree rather than oppose. (C) \"Instead\" signals replacement, yet the museum did both things, not one in place of the other. (D) \"Otherwise\" introduces what would happen if the first action were not taken, a conditional alternative the sentence does not present." },
  { id: "t21rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The reviewer found the novel's plot ______, complaining that nearly every twist could be guessed chapters in advance.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["predictable", "intricate", "startling", "original"], correct: 0, explanation: "The answer is \"predictable\" (A). The passage says nearly every twist \"could be guessed chapters in advance,\" and a plot whose turns can be foreseen is by definition predictable, matching the reviewer's complaint. (B) \"intricate\" means complex and tangled, which would make twists harder, not easier, to anticipate. (C) \"startling\" means shocking or surprising, the direct opposite of something already guessed. (D) \"original\" means fresh and unexpected, contradicting twists the reader can call in advance." },
  { id: "t21rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Bees communicate the location of food by performing a 'waggle dance,' whose angle and duration encode the direction and distance to a flower patch.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees use a dance to tell hive mates where food is located.", "Bees cannot share information about food.", "The waggle dance has no meaning.", "Bees dance only to attract mates."], correct: 0, explanation: "The answer is (A). The text says the dance's angle and duration \"encode the direction and distance to a flower patch,\" so the dance tells hive mates where food is, exactly what A states. (B) contradicts the text, which shows bees do share food information through the dance. (C) contradicts the statement that the dance encodes specific meaning. (D) introduces mating, a purpose the passage never mentions; the dance is described only as communicating food location." },
  { id: "t21rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the coach nor the players ______ satisfied with the referee's final call.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "The answer is \"were\" (B). With a \"neither...nor\" subject, the proximity rule applies: the verb agrees with the nearer subject, here the plural \"players,\" so the plural \"were\" is required. (A) \"was\" is singular and mismatches the plural \"players\" closest to the verb. (C) \"is\" is singular and also breaks the proximity-rule agreement. (D) \"has been\" is singular as well, so it likewise fails to agree with the nearer plural noun." },
  { id: "t21rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first prototype overheated within minutes. ______, the engineers gained data that guided a far more reliable second design.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For example", "Therefore", "In short"], correct: 0, explanation: "The answer is \"Still\" (A). The prototype's overheating was a failure, yet the engineers nonetheless gained useful data, so a concessive contrast transition fits. (B) \"For example\" introduces an illustration of a prior point, but the data is not an example of overheating. (C) \"Therefore\" marks a result, which would wrongly imply the engineers overheated the prototype on purpose to get the data. (D) \"In short\" signals a summary, but the second sentence adds new information rather than restating the first." },
  { id: "t21rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A clinic recorded average wait times of 12 minutes on Mondays, 9 minutes on Wednesdays, and 6 minutes on Fridays.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Wait times were longest on Mondays.", "Wait times were longest on Fridays.", "Wednesday and Friday waits were equal.", "All three days had identical wait times."], correct: 0, explanation: "The answer is (A). Comparing the figures—12 minutes Monday, 9 Wednesday, 6 Friday—Monday's 12 is the largest, so waits were longest on Mondays. (B) inverts the data: Friday's 6 minutes is actually the shortest wait, not the longest. (C) claims Wednesday and Friday were equal, but 9 and 6 are different values. (D) says all three were identical, contradicting the three distinct numbers given." },
  { id: "t21rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive holds a manuscript ______ scholars believe was copied by a single scribe over many years.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The relative pronoun \"that\" introduces the clause modifying \"manuscript.\" \"What\" cannot follow a noun antecedent, \"where\" marks place not object, and \"and it\" creates a comma-spliced run-on." },
  { id: "t21rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Rushing to catch the train, ______ the briefcase was left behind on the platform bench.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["rushing to catch the train, the briefcase was left behind on the platform bench", "the commuter, rushing to catch the train, left her briefcase behind on the platform bench", "the platform bench held the briefcase, rushing to catch the train", "left behind, the train was caught by the commuter rushing"], correct: 1, explanation: "The answer is (B). The introductory phrase \"Rushing to catch the train\" must be followed immediately by the noun that performs the rushing; only B supplies \"the commuter,\" a person who can rush. (A) leaves \"the briefcase\" as the subject right after the modifier, so the briefcase illogically does the rushing—a classic dangling modifier. (C) makes \"the platform bench\" the thing rushing to catch the train, which is equally illogical. (D) attaches the rushing to \"the train\" being caught, again pairing the modifier with a noun that cannot rush." },
  { id: "t21rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A geologist argues that the canyon was carved primarily by a single ancient flood rather than by slow erosion, pointing to its steep, uniform walls.", prompt: "Which finding, if true, would most strengthen the geologist's argument?", type: "mcq", choices: ["Canyons known to form gradually have gently sloped, irregular walls.", "The canyon contains many species of fish.", "Slow erosion is common in other regions.", "The canyon is a popular tourist destination."], correct: 0, explanation: "The answer is (A). The geologist's evidence is the canyon's \"steep, uniform walls\"; if canyons known to form gradually instead have gently sloped, irregular walls, then this canyon's contrasting walls support sudden flood formation, strengthening the argument. (B) the presence of many fish species says nothing about how the canyon was carved. (C) noting that slow erosion is common elsewhere does not address this canyon's specific wall shape. (D) the canyon's popularity with tourists is irrelevant to its geological origin." },
  { id: "t21rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with the lead actors, ______ rehearsing the final scene late into the night.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "are", "have been"], correct: 0, explanation: "The answer is \"was\" (A). The subject is the singular \"director\"; a phrase set off by commas with \"together with\" is parenthetical and never changes the subject's number, so a singular verb is required. (B) \"were\" is plural and wrongly agrees with the parenthetical \"lead actors\" instead of \"director.\" (C) \"are\" is plural and present tense, mismatching both the singular subject and the past-time context. (D) \"have been\" is plural as well, so it likewise fails to agree with the singular \"director.\"" },
  { id: "t21rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to emphasize that two separate studies reached the same surprising result. ______, both teams found that the vaccine remained effective after a full year.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "The answer is \"Remarkably\" (B). The researcher wants to stress that two separate studies reached the same surprising result, so a transition emphasizing how striking the agreement is fits best. (A) \"By contrast\" signals opposition, but the two teams agreed rather than differed. (C) \"However\" also marks contradiction, contradicting the matching findings. (D) \"Otherwise\" introduces an alternative outcome, which has no place when both studies converged on one result." },
  { id: "t21rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The essay's tone is studiously ______: it refuses to celebrate or condemn its subject, instead laying out the evidence and stepping aside.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["neutral", "scathing", "adoring", "frantic"], correct: 0, explanation: "The answer is \"neutral\" (A). The tone \"refuses to celebrate or condemn,\" instead laying out evidence and stepping aside, which is the definition of a balanced, neutral stance. (B) \"scathing\" means harshly critical, an extreme form of condemning that the essay refuses. (C) \"adoring\" means full of praise, the celebrating the essay also avoids. (D) \"frantic\" describes panicked agitation, which has nothing to do with the calm, evidence-first detachment described." },
  { id: "t21rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate applies only to vehicles purchased new after January and registered to a resident of the state.", prompt: "Which vehicle clearly qualifies for the rebate?", type: "mcq", choices: ["A new car bought in March and registered to a state resident.", "A used car bought in March by a state resident.", "A new car bought in March and registered out of state.", "A new car bought the previous December."], correct: 0, explanation: "All three conditions—new, purchased after January, registered to a state resident—are met only in A. B fails the \"new\" rule, C fails the residency rule, and D was bought before January." },
  { id: "t21rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the leaking roof ______ they repainted the weathered shutters.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["roof, and then", "roof and, then", "roof then", "roof, then"], correct: 0, explanation: "The answer is \"roof, and then\" (A). The two independent clauses are correctly joined by a comma plus the coordinating conjunction \"and\"; \"then\" is just an adverb that follows. (B) \"roof and, then\" misplaces the comma after \"and,\" wrongly separating the conjunction from the clause it introduces. (C) \"roof then\" omits the conjunction entirely, fusing two complete clauses into a run-on. (D) \"roof, then\" uses only a comma to join the clauses, producing a comma splice." },
  { id: "t21rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although she had a reputation for being ______, the editor surprised the young writer with pages of patient, encouraging notes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["severe", "generous", "timid", "patient"], correct: 0, explanation: "The answer is \"severe\" (A). \"Although\" sets up a contrast between her reputation and her actual patient, encouraging notes, so her reputation must be the opposite of kind—that is, harsh or severe. (B) \"generous\" matches the kind notes rather than contrasting with them, breaking the \"Although\" logic. (C) \"timid\" describes shyness, which neither contrasts with nor explains pages of encouraging feedback. (D) \"patient\" is the very quality her notes display, so it cannot be the reputation that surprised the writer." },
  { id: "t21rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist observes that towns that built rail connections in the 1800s industrialized faster than isolated towns, attributing the difference to cheaper movement of goods.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Rail links lowered transport costs, speeding industrial growth.", "Isolated towns industrialized fastest.", "Railroads slowed nearby towns' growth.", "Town location had no effect on industry."], correct: 0, explanation: "The answer is (A). The economist says rail-connected towns industrialized faster and attributes this to cheaper movement of goods, so A restates that lower transport costs sped industrial growth. (B) inverts the finding: the isolated towns industrialized more slowly, not fastest. (C) reverses the effect, claiming railroads slowed growth, the opposite of what the data show. (D) denies any role for location, contradicting the very difference the economist explains." },
  { id: "t21rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The council delayed the vote ______ several members had not yet reviewed the revised budget.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "The answer is \"vote because\" (A). When a dependent clause introduced by the subordinating conjunction \"because\" follows the main clause, no punctuation is needed between them. (B) \"vote, because\" inserts an unnecessary comma before a trailing because-clause. (C) \"vote; because\" uses a semicolon, but a semicolon must join two independent clauses and cannot precede a subordinate \"because\" clause. (D) \"vote: because\" uses a colon, which introduces a list or explanation, not a because-clause attached to the main clause." },
  { id: "t21rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory switched to recycled materials. ______, it cut its raw-material costs by nearly a third.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The answer is \"As a result\" (A). The cost cut follows directly from switching to recycled materials, a cause-and-effect link. (B) \"Nevertheless\" signals contrast, wrongly implying the savings happened despite the switch. (C) \"For example\" introduces an illustration, but lower costs are a consequence, not an instance of switching materials. (D) \"On the other hand\" marks an opposing point, which does not fit a straightforward result." },
  { id: "t21rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach offered ______ feedback, pointing out exactly which footwork to change before the next match.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "vague", "irrelevant", "evasive"], correct: 0, explanation: "The answer is \"specific\" (A). Pointing out \"exactly which footwork to change\" is precise, detailed guidance, which is what specific feedback means. (B) \"vague\" means unclear or imprecise, the opposite of naming an exact change. (C) \"irrelevant\" means off-topic, but footwork notes directly concern the player's performance. (D) \"evasive\" means dodging the point, contradicting feedback that pinpoints exactly what to fix." },
  { id: "t21rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Researchers found that planting hedgerows along farm fields increased the number of pollinating insects, which in turn raised the yield of nearby crops that depend on pollination.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Hedgerows boosted pollinators, which increased pollination-dependent crop yields.", "Hedgerows reduced crop yields directly.", "Pollinators declined after hedgerows were planted.", "Crops grew best with no pollinators."], correct: 0, explanation: "The answer is (A). The text describes a chain: hedgerows increased pollinating insects, which in turn raised yields of pollination-dependent crops, exactly what A states. (B) reverses the result, claiming hedgerows reduced yields, the opposite of the increase described. (C) contradicts the first link, since pollinators rose rather than declined. (D) contradicts the premise that the crops depend on pollination, so they cannot grow best without pollinators." },
];

// ─────────────────────── PRACTICE TEST 21 · R&W M2 easy (27) ─────────────────
const T21_RW_M2E: SatQuestion[] = [
  { id: "t21rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The lemonade was too ______, so I stirred in another spoonful of sugar.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["sour", "sweet", "cold", "green"], correct: 0, explanation: "The answer is \"sour\" (A). Stirring in more sugar is a fix for lemonade that tastes too tart, so the drink was too sour. (B) \"sweet\" is the opposite problem; you would not add sugar to something already too sweet. (C) \"cold\" describes temperature, which sugar does not change. (D) \"green\" describes color, which has nothing to do with adjusting taste." },
  { id: "t21rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are\" (B). The subject \"three puppies\" is plural, so it needs the plural present-tense verb \"are.\" (A) \"is\" is singular and cannot agree with a plural subject. (C) \"was\" is singular and past tense, mismatching both number and the ongoing action. (D) \"am\" is the first-person singular form, used only with \"I,\" not with \"puppies.\"" },
  { id: "t21rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bats are not blind; many use sound that bounces off objects to find their way and catch insects in the dark.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bats use echoes of sound to navigate and hunt.", "Bats cannot find food at night.", "Bats are completely blind.", "Bats never make any sound."], correct: 0, explanation: "The answer is (A). The text says bats \"use sound that bounces off objects to find their way and catch insects,\" which is using echoes to navigate and hunt. (B) contradicts the text, which states bats do catch insects in the dark. (C) contradicts the opening claim that bats \"are not blind.\" (D) contradicts the passage, since the bats clearly make the sound they rely on." },
  { id: "t21rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The rain was pouring down hard. ______, we decided to stay indoors.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The answer is \"So\" (B). The heavy rain is the cause and staying indoors is its effect, so a cause-and-effect transition fits. (A) \"For example\" introduces an illustration, but staying indoors is a consequence, not an example of rain. (C) \"However\" signals contrast, yet the two ideas agree rather than oppose. (D) \"Meanwhile\" marks simultaneous events, but the second sentence results from the first rather than happening alongside it." },
  { id: "t21rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at my grandmother's house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "The answer is \"ate\" (C). The time marker \"Last night\" places the action in the past, so the past-tense \"ate\" is required. (A) \"eat\" is present tense and cannot describe a completed past meal. (B) \"eats\" is third-person singular present, wrong in both tense and subject agreement with \"we.\" (D) \"eating\" is a bare participle that cannot stand alone as the main verb without a helping verb." },
  { id: "t21rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The bakery smelled ______, full of fresh bread and warm cinnamon.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["wonderful", "terrible", "empty", "quiet"], correct: 0, explanation: "The answer is \"wonderful\" (A). Fresh bread and warm cinnamon are pleasant scents, so the bakery smelled wonderful. (B) \"terrible\" is the opposite, an unpleasant reaction the appealing smells do not support. (C) \"empty\" describes a lack of contents, not a smell. (D) \"quiet\" describes sound, not scent, so it cannot complete \"smelled.\"" },
  { id: "t21rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives you exercise, and reduces traffic on busy streets.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is dangerous.", "Walking to school costs a lot.", "Walking to school adds traffic."], correct: 0, explanation: "The answer is (A). The text lists three good things about walking to school—saving money, getting exercise, and reducing traffic—so its main idea is that walking has several benefits. (B) contradicts the text, which presents walking positively rather than as dangerous. (C) contradicts \"saves money\"; the text says walking is cheaper, not costly. (D) contradicts \"reduces traffic\"; walking lowers traffic rather than adding to it." },
  { id: "t21rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "We waited nearly ______ hour for the museum doors to open.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "The answer is \"an\" (B). \"Hour\" begins with a silent h, so it opens with a vowel sound, and the article \"an\" is used before vowel sounds. (A) \"a\" is used before consonant sounds, but the h in \"hour\" is not pronounced. (C) \"the only\" changes the meaning to a unique hour the sentence does not intend. (D) \"some\" implies an unspecified quantity, distorting the idea of waiting nearly one hour." },
  { id: "t21rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puzzle was ______, so we solved it in just a few minutes.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["simple", "impossible", "endless", "confusing"], correct: 0, explanation: "Solving it quickly means the puzzle was \"simple.\" The other words all suggest difficulty, contradicting the fast solution." },
  { id: "t21rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and I ______ planning a surprise party for our parents.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The compound subject \"my sister and I\" is plural, so \"are\" agrees. The singular verbs do not match a two-person subject." },
  { id: "t21rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Tree rings record a tree's age: each year the tree adds one new ring, so counting rings tells how old it is.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Counting a tree's rings reveals its age.", "Trees lose a ring each year.", "Tree rings have no meaning.", "Trees never grow new rings."], correct: 0, explanation: "Each year adds a ring, so counting rings gives the age (A). B, C, and D each contradict the explanation given." },
  { id: "t21rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, the whole neighborhood lit candles.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "Lighting candles follows from the power outage, so \"As a result\" fits. The other choices signal contrast, example, or replacement." },
  { id: "t21rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the gardener ______ the roses before sunset.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["water", "waters", "watered", "watering"], correct: 2, explanation: "\"Yesterday\" requires the past tense \"watered.\" The present-tense forms and the bare participle do not express completed past action." },
  { id: "t21rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After the long hike, the campers were ______ and fell asleep quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "wide awake", "bored", "excited"], correct: 0, explanation: "Falling asleep quickly shows the campers were \"tired.\" \"Wide awake\" and \"excited\" contradict quick sleep, and \"bored\" does not explain sleepiness." },
  { id: "t21rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The café serves breakfast from 7 a.m. to 11 a.m. but does not serve it in the afternoon.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot order breakfast at 2 p.m.", "Breakfast is served all day.", "The café opens at midnight.", "Breakfast ends at 7 a.m."], correct: 0, explanation: "Breakfast stops at 11 a.m., so 2 p.m. is too late (A). B contradicts the stated hours, and C and D misread the opening and ending times." },
  { id: "t21rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after the meal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The singular possessive \"its\" matches the singular \"cat.\" \"It's\" means \"it is,\" \"their\" is plural, and \"they're\" means \"they are.\"" },
  { id: "t21rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals sleep through the winter. ______, bears hibernate in their dens until spring.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "Bears are an example of an animal that sleeps through winter, so \"For example\" fits. The other transitions signal contrast or alternatives." },
  { id: "t21rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The hallway was very ______, so we whispered to avoid echoes.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["quiet", "loud", "bright", "warm"], correct: 0, explanation: "Whispering to avoid echoes suggests a \"quiet\" hallway. \"Loud\" is the opposite, and \"bright\" and \"warm\" do not relate to sound." },
  { id: "t21rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The new books ______ arranged on the lower shelf.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Books\" is plural, so the plural verb \"are\" agrees. The singular forms do not match a plural subject." },
  { id: "t21rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Salt was once so valuable that Roman soldiers were sometimes paid in it, a practice that gave us the word 'salary.'", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Salt was once valuable enough to serve as pay.", "Salt has always been worthless.", "Roman soldiers were never paid.", "Salt has no link to any English word."], correct: 0, explanation: "Soldiers paid in salt shows it was valuable enough to use as pay (A). B and C contradict the passage, and D ignores the link to \"salary.\"" },
  { id: "t21rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned a picnic at the park. ______, a sudden downpour forced us inside.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "Planning a picnic but being forced inside is a contrast, so \"However\" fits. \"Therefore\" and \"Similarly\" suggest a result or likeness, and \"For example\" introduces an instance." },
  { id: "t21rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next year my class ______ to visit the science museum.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["hope", "hopes", "hoped", "hoping"], correct: 1, explanation: "The singular collective noun \"class\" takes \"hopes,\" and the present tense suits a stated future plan. The plural \"hope,\" past \"hoped,\" and bare participle do not fit." },
  { id: "t21rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was so ______ that I could barely lift it onto my shoulders.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "soft", "small"], correct: 0, explanation: "Barely able to lift it means the backpack was \"heavy.\" \"Light,\" \"soft,\" and \"small\" do not explain the difficulty lifting it." },
  { id: "t21rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Drinking water keeps the body cool, helps it carry nutrients, and supports clear thinking.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Drinking water helps the body in several ways.", "Drinking water harms the body.", "Water has only one use.", "The body needs no water."], correct: 0, explanation: "Three benefits are listed, so the text is about water's several benefits (A). B, C, and D each contradict the positive points." },
  { id: "t21rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She picked ______ apple from the bowl on the counter.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Apple\" begins with a vowel sound, so \"an\" is correct. \"A\" precedes consonant sounds, and the other choices change the meaning." },
  { id: "t21rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The instructions were clear and short. ______, the project took only an afternoon to finish.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "However", "Instead", "Otherwise"], correct: 0, explanation: "Finishing quickly results from the clear instructions, so \"As a result\" fits. The other transitions signal contrast or replacement." },
  { id: "t21rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the dove appear from nowhere.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "A surprising trick leaves an audience \"amazed.\" \"Bored,\" \"sleepy,\" and \"angry\" do not match a delighted reaction to a magic trick." },
];

// ─────────────────────── PRACTICE TEST 21 · R&W M2 hard (27) ─────────────────
const T21_RW_M2H: SatQuestion[] = [
  { id: "t21rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The official's statement was a masterpiece of ______, seeming to promise reform while committing to nothing the public could later hold him to.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["obfuscation", "candor", "precision", "transparency"], correct: 0, explanation: "Seeming to promise while committing to nothing is deliberate \"obfuscation\" (clouding meaning). \"Candor,\" \"precision,\" and \"transparency\" all denote clarity, the opposite of what is described." },
  { id: "t21rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The chapter opens with a sweeping claim about human nature, then narrows steadily through historical cases until it rests on a single, closely examined diary entry.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from a broad generalization to one specific example.", "It begins with a single example and never generalizes.", "It lists unrelated facts in no order.", "It repeats one claim without support."], correct: 0, explanation: "A sweeping claim narrowing to a single diary entry moves from general to specific (A). B reverses the order, and C and D mischaracterize the deliberate narrowing structure." },
  { id: "t21rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A reservoir was at 88% capacity in spring, 84% in early summer, and 61% by late summer of the same year.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The level dropped more sharply later in the year than earlier.", "The reservoir filled up over the summer.", "The level stayed constant all year.", "The reservoir was empty by early summer."], correct: 0, explanation: "An 88-to-84 drop is small, but 84-to-61 is a much larger fall, so the decline steepened later (A). B and C contradict the falling figures, and D contradicts the 84% reading." },
  { id: "t21rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The merger would expand the company's reach into new markets. ______, it would require laying off hundreds of overlapping employees.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "A clear benefit followed by a serious cost is a contrast, signaled by \"However.\" \"Therefore,\" \"Likewise,\" and \"Accordingly\" imply consequence or similarity, not the trade-off described." },
  { id: "t21rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write clear reports, and ______ their findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure with \"to analyze\" and \"to write\" requires the infinitive \"to present.\" The gerund and bare or past forms break the parallel series." },
  { id: "t21rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ its author's youth, dwelling as honestly on his cruelties as on his kindnesses.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sentimentalize", "examine", "recall", "describe"], correct: 0, explanation: "Dwelling honestly on cruelties as well as kindnesses means the memoir refuses to \"sentimentalize\" (gloss over with rosy feeling) the past. The other verbs do not capture the rejection of sugar-coating." },
  { id: "t21rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where earlier economists treated unemployment as a sign of individual failing, the newer framework casts it as a structural feature of fluctuating markets.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older view of unemployment with a newer, structural one.", "To prove unemployment is always voluntary.", "To summarize only the older economists' view.", "To argue unemployment does not exist."], correct: 0, explanation: "The \"Where earlier...the newer...\" construction contrasts two views of unemployment (A). B and D distort the text's claims, and C ignores the newer framework it presents." },
  { id: "t21rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The day shift cleared the backlog with ease ______ the night shift fell hopelessly behind on the very same task.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["ease, the", "ease; the", "ease the", "ease: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone makes a splice, no punctuation creates a run-on, and a colon does not fit two contrasting clauses." },
  { id: "t21rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the lecture was packed with qualifications, caveats, and competing interpretations that left no claim unguarded.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["simplistic", "nuanced", "intricate", "cautious"], correct: 0, explanation: "\"Far from\" signals the opposite of what follows; a lecture full of qualifications is the opposite of \"simplistic.\" \"Nuanced,\" \"intricate,\" and \"cautious\" all describe the lecture rather than its opposite." },
  { id: "t21rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters claim the new highway eased congestion. Yet a year after it opened, average commute times across the region rose by seven minutes.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It presents evidence that complicates the supporters' claim.", "It restates the supporters' claim exactly.", "It confirms that congestion eased.", "It proposes building a second highway."], correct: 0, explanation: "Longer commute times complicate the claim that the highway eased congestion (A). B and C ignore the contradicting evidence, and D introduces a proposal the text never makes." },
  { id: "t21rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The voyage required three essentials ______ a seaworthy vessel, a skilled crew, and accurate charts.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials,", "essentials:", "essentials;", "essentials"], correct: 1, explanation: "A colon introduces the list that specifies the \"three essentials\" after an independent clause. A comma is too weak, a semicolon needs two independent clauses, and no punctuation leaves the list unmarked." },
  { id: "t21rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The forecast correctly identified the cold front days in advance. ______, it badly underestimated how much snow the front would drop.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "A success followed by a notable failure is a concession, best signaled by \"Nonetheless.\" \"Indeed\" and \"Likewise\" reinforce, and \"Therefore\" marks a result, none fitting the reversal." },
  { id: "t21rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, the new coating made the lenses 40% more scratch-resistant, but it also reduced how much light passed through them by 15%.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The coating improved durability but lowered light transmission.", "The coating improved both durability and light transmission.", "The coating had no measurable effect.", "Uncoated lenses were more scratch-resistant."], correct: 0, explanation: "The coating raised scratch resistance (+40%) while cutting light transmission (−15%) (A). B and D misread the trade-off, and C ignores both measured effects." },
  { id: "t21rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The sculpture displayed near the entrance ______ to a period long before the artist's celebrated bronze figures.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The singular subject \"sculpture\" (not the plural \"figures\" in the modifier) takes the singular verb \"belongs.\" The plural, participial, and infinitive forms fail subject-verb agreement." },
  { id: "t21rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The teacher prized ______ above cleverness, rewarding students who admitted what they did not yet understand.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["candor", "showmanship", "secrecy", "arrogance"], correct: 0, explanation: "Rewarding students who admit what they do not know prizes honesty, or \"candor.\" \"Showmanship,\" \"secrecy,\" and \"arrogance\" all conflict with openly admitting ignorance." },
  { id: "t21rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author begins by conceding that early telescopes were crude and easily distorted images, then argues that wrestling with these flaws drove the optical innovations that made later instruments sharp.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It treats an early weakness as the spur for later strengths.", "It denies early telescopes had any flaws.", "It claims telescopes never improved.", "It lists telescope prices over time."], correct: 0, explanation: "The crude early flaws are recast as what drove later improvements, turning a weakness into a strength (A). B and C contradict the text, and D names a topic it never addresses." },
  { id: "t21rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having studied the score for months ______ the conductor led the orchestra without once glancing at the page.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the orchestra was led without once glancing at the page", "the conductor led the orchestra without once glancing at the page", "without glancing at the page, the score was led", "leading the orchestra, the score was studied for months"], correct: 1, explanation: "Only choice B places the person who studied the score—the conductor—right after the modifier. The other options make the orchestra or the score perform the studying, a dangling modifier." },
  { id: "t21rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The drug cleared the infection rapidly in cell cultures. ______, in human patients the same dose produced only a modest, slow improvement.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In human patients, by contrast", "For this reason", "Similarly"], correct: 1, explanation: "The shift from fast results in cultures to slow ones in patients is a contrast, captured by \"In human patients, by contrast.\" The other options signal consequence or similarity, not the gap described." },
  { id: "t21rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, in which a brief opening motif returns, transformed, to anchor each of its four movements.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "fragmented", "aimless", "chaotic"], correct: 0, explanation: "A motif that recurs to anchor every movement gives the work a \"cohesive\" design. \"Fragmented,\" \"aimless,\" and \"chaotic\" describe the opposite of a unified structure." },
  { id: "t21rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across six schools, those that added a daily reading period saw test scores climb by an average of 11%, while schools that kept their usual schedule saw essentially no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding a daily reading period was associated with higher test scores.", "Keeping the usual schedule raised scores most.", "Reading periods had no relationship to scores.", "All six schools added a reading period."], correct: 0, explanation: "Schools that added reading rose 11% while others did not, linking the period to higher scores (A). B and C contradict the figures, and D contradicts \"schools that kept their usual schedule.\"" },
  { id: "t21rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The composer's early sketches — rough, hurried, and full of crossings-out ______ already revealed the themes that would define her later symphonies.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["out —", "out,", "out", "out;"], correct: 0, explanation: "A pair of dashes sets off the interrupting description, so the second dash must close it. A comma, no punctuation, or a semicolon would leave the dash pair unmatched." },
  { id: "t21rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The board dismissed the auditor's concerns as ______, only to face the exact financial collapse she had predicted.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overblown", "prophetic", "accurate", "urgent"], correct: 0, explanation: "Dismissing warnings that then come true means the board wrongly judged them \"overblown\" (exaggerated). \"Prophetic,\" \"accurate,\" and \"urgent\" would mean the board took the concerns seriously, contradicting \"dismissed.\"" },
  { id: "t21rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One historian credits the empire's fall to overextended borders; another blames a collapsing currency. A third contends that the weak borders and the failing currency fed on each other.", prompt: "Which choice best describes the third historian's position?", type: "mcq", choices: ["The two proposed causes reinforced each other to bring the fall.", "Neither borders nor currency mattered at all.", "Only overextended borders mattered.", "The empire never actually fell."], correct: 0, explanation: "The third historian says the two causes \"fed on each other,\" meaning they reinforced one another (A). B, C, and D each ignore or contradict that combined explanation." },
  { id: "t21rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The technicians rebuilt the turbine ______ the original had cracked under repeated thermal stress.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["turbine, the", "turbine; the", "turbine the", "turbine: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone makes a splice, no punctuation creates a run-on, and a colon does not fit two complete clauses here." },
  { id: "t21rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the festival's costs fell unevenly on residents. ______, downtown shops gained customers while outlying neighborhoods bore the traffic and noise.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The second sentence gives a concrete illustration of the uneven costs, so \"Specifically\" fits. \"In contrast\" and \"Nevertheless\" signal opposition, and \"Otherwise\" introduces an alternative outcome." },
  { id: "t21rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying up every thread, the director leaves the protagonist's fate ______, inviting viewers to imagine what becomes of her.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "settled", "obvious", "decided"], correct: 0, explanation: "Declining to tie up threads and inviting viewers to imagine leaves the fate \"ambiguous.\" \"Settled,\" \"obvious,\" and \"decided\" all describe a resolved ending, contradicting the open invitation." },
  { id: "t21rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her experiment ran for only a few weeks, yet she argues that the effect she measured was so strong and steady that it justifies a longer, larger study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She admits a limitation while defending the result's importance.", "She claims her experiment had no weaknesses.", "She abandons her finding entirely.", "She argues no further study is warranted."], correct: 0, explanation: "She acknowledges the short duration yet defends the finding as worth pursuing further (A). B denies the conceded limitation, and C and D contradict her call for a larger study." },
];

// ─────────────────────── PRACTICE TEST 21 · MATH M1 (22) ─────────────────────
const T21_M_M1: SatQuestion[] = [
  { id: "t21m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: isolate x. Subtract 8 from both sides: 5x = 35. Divide by 5: x = 7. Check: 5(7) + 8 = 35 + 8 = 43. Trap: forgetting to subtract 8 first gives a wrong value." },
  { id: "t21m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 4 cups of rice to serve 6 people. How many cups are needed to serve 15 people?", type: "mcq", choices: ["10", "9", "11", "12"], correct: 0, explanation: "Goal: scale the ratio. Per person: 4/6 = 2/3 cup. For 15 people: (2/3)(15) = 30/3 = 10 cups. Check: 10 cups for 15 people keeps the 2:3 ratio. Trap: scaling by people difference (15−6=9) instead of the ratio." },
  { id: "t21m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 4, what is the value of f(2)?", type: "mcq", choices: ["8", "2", "20", "5"], correct: 0, explanation: "Goal: evaluate the function at x = 2. Substitute: f(2) = 3(2²) − 4. Compute the square first: 2² = 4, so 3(4) = 12, then 12 − 4 = 8. Trap: squaring after multiplying, e.g. (3·2)² = 36, ignores order of operations." },
  { id: "t21m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 18. What is its radius?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the radius from the diameter. The radius is half the diameter: 18 ÷ 2 = 9. Check: doubling 9 returns the diameter 18. Trap: confusing radius with diameter and answering 18 or 36." },
  { id: "t21m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 3x + 2 passes through the point (4, k). What is the value of k?", type: "grid", gridAnswers: ["14"], explanation: "Goal: find y when x = 4. Substitute into the line: k = 3(4) + 2. Multiply first: 3(4) = 12, then add 2: k = 14. Check: the point (4, 14) satisfies y = 3x + 2. Trap: adding before multiplying gives a wrong value." },
  { id: "t21m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: back out the missing value from the mean. Mean 9 over 3 numbers means the total is 9 × 3 = 27. The known numbers sum to 6 + 10 = 16, so x = 27 − 16 = 11. Check: (6+10+11)/3 = 27/3 = 9. Trap: forgetting to multiply the mean by the count." },
  { id: "t21m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 7 = 22, what is the value of x?", type: "mcq", choices: ["5", "15", "9", "29"], correct: 0, explanation: "Goal: solve for x. Subtract 7: 3x = 15. Divide by 3: x = 5. Check: 3(5) + 7 = 15 + 7 = 22. Trap: dividing 22 by 3 before subtracting 7 gives a wrong value." },
  { id: "t21m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the sum of the roots. Factor: (x − 4)(x − 5) = 0, giving roots 4 and 5. Their sum is 4 + 5 = 9, which also equals −b/a = −(−9)/1 = 9. Check: both methods agree. Trap: summing as if the roots were the constants −9 and 20." },
  { id: "t21m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A backpack's price rose from $40 to $48. What was the percent increase?", type: "mcq", choices: ["20%", "8%", "16%", "120%"], correct: 0, explanation: "Goal: find the percent increase. The increase is 48 − 40 = 8. Divide by the original: 8/40 = 0.2 = 20%. Check: 20% of 40 is 8, the actual increase. Trap: dividing by the new price 48 instead of the original 40." },
  { id: "t21m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 40° and 85°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["55"], explanation: "Goal: use the triangle angle sum. The three angles total 180°, so the third is 180 − 40 − 85 = 55°. Check: 40 + 85 + 55 = 180. Trap: using 360° instead of 180° for a triangle." },
  { id: "t21m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $30 per hour. Which equation gives the total cost C for h hours?", type: "mcq", choices: ["C = 30h + 40", "C = 40h + 30", "C = 70h", "C = 30h − 40"], correct: 0, explanation: "Goal: model fixed plus variable cost. The flat $40 fee is added once, and $30 is charged for each hour h, giving C = 30h + 40. Check: for h = 0, C = 40, the base fee. Trap: swapping the rate and the fee to get C = 40h + 30." },
  { id: "t21m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 4)(x − 1) = x² + bx − 4, what is the value of b?", type: "grid", gridAnswers: ["3"], explanation: "Goal: match coefficients after expanding. (x + 4)(x − 1) = x² − x + 4x − 4 = x² + 3x − 4. The middle coefficient gives b = 3. Check: the constant −4 also matches. Trap: forgetting the inner and outer terms combine to +3x, not −4x." },
  { id: "t21m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 250 people, 36% said they bike to work. How many people bike to work?", type: "mcq", choices: ["90", "85", "72", "100"], correct: 0, explanation: "Goal: take a percent of a total. Convert 36% to 0.36 and multiply: 0.36 × 250 = 90. Check: 10% of 250 is 25, and 36% is a bit over a third of 250, near 90. Trap: misplacing the decimal to get 9 or 900." },
  { id: "t21m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 3) = 2x + 9, what is the value of x?", type: "mcq", choices: ["8", "4", "6", "12"], correct: 0, explanation: "Goal: solve a linear equation. Distribute: 5x − 15 = 2x + 9. Subtract 2x: 3x − 15 = 9. Add 15: 3x = 24, so x = 8. Check: 5(8−3) = 25 and 2(8)+9 = 25. Trap: forgetting to distribute the 5 to the −3." },
  { id: "t21m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(length + width) = 2(12 + 5) = 2(17) = 34. Check: the two long sides total 24 and the two short sides total 10, summing to 34. Trap: computing area 12 × 5 = 60 instead of perimeter." },
  { id: "t21m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve an exponential equation by matching bases. Write 27 as 3³, so 3^(x−1) = 3³ means x − 1 = 3. Add 1: x = 4. Check: 3^(4−1) = 3³ = 27. Trap: dividing 27 by 3 instead of equating exponents." },
  { id: "t21m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 40 miles. Two towns are 3.5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["140", "120", "160", "135"], correct: 0, explanation: "Goal: convert map inches to real miles. Multiply distance by the scale: 3.5 × 40 = 140 miles. Check: 3 inches is 120 miles and the extra half inch adds 20, totaling 140. Trap: rounding 3.5 down to 3 and answering 120." },
  { id: "t21m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: compute slope as rise over run. Slope = (15 − 3)/(6 − 2) = 12/4 = 3. Check: moving 4 right and 12 up gives a slope of 3. Trap: inverting to run over rise, giving 1/3." },
  { id: "t21m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x − 5, what value of x makes f(x) = 19?", type: "mcq", choices: ["6", "5", "7", "4"], correct: 0, explanation: "Goal: solve f(x) = 19 for x. Set 4x − 5 = 19. Add 5: 4x = 24. Divide by 4: x = 6. Check: f(6) = 4(6) − 5 = 24 − 5 = 19. Trap: adding 5 to 19 then forgetting to divide by 4." },
  { id: "t21m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 7. What is its area, in terms of π?", type: "mcq", choices: ["49π", "14π", "7π", "21π"], correct: 0, explanation: "Goal: find the area of a circle. Use A = πr² with r = 7: A = π(7²) = 49π. Check: squaring the radius before multiplying by π is required. Trap: using the circumference formula 2πr = 14π instead of the area." },
  { id: "t21m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 2x − y = 9 and y = 5, what is the value of x?", type: "mcq", choices: ["7", "2", "9", "14"], correct: 0, explanation: "Goal: substitute and solve. Replace y with 5: 2x − 5 = 9. Add 5: 2x = 14. Divide by 2: x = 7. Check: 2(7) − 5 = 14 − 5 = 9. Trap: forgetting to divide by 2 after reaching 2x = 14." },
  { id: "t21m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 30-hour week?", type: "grid", gridAnswers: ["660"], explanation: "Goal: find total pay from rate and hours. Multiply: 22 × 30 = 660 dollars. Check: 22 × 3 = 66, then append a zero for 30 hours to get 660. Trap: adding instead of multiplying, e.g. 22 + 30 = 52." },
];

