const T21_M_M2E: SatQuestion[] = [
  { id: "t21m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 9 = 21, what is the value of x?", type: "grid", gridAnswers: ["12"], explanation: "Goal: isolate x. Subtract 9 from both sides: x = 21 − 9 = 12. Check: 12 + 9 = 21. Trap: adding 9 instead of subtracting it." },
  { id: "t21m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 20% of 80?", type: "mcq", choices: ["16", "20", "40", "8"], correct: 0, explanation: "Goal: take a percent of a number. Convert 20% to 0.20 and multiply: 0.20 × 80 = 16. Check: 10% of 80 is 8, so 20% is double, 16. Trap: answering 20 by confusing the percent with the result." },
  { id: "t21m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 9 and a width of 4. What is its area?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find area. Multiply length by width: 9 × 4 = 36. Check: four rows of nine units gives 36 squares. Trap: computing the perimeter 2(9+4) = 26 instead of area." },
  { id: "t21m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 8x = 56, what is the value of x?", type: "mcq", choices: ["7", "8", "48", "64"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 8: x = 56 ÷ 8 = 7. Check: 8 × 7 = 56. Trap: subtracting 8 from 56 instead of dividing." },
  { id: "t21m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: evaluate following order of operations. Square first: 5² = 25, then subtract 4: 25 − 4 = 21. Check: 21 + 4 returns 25. Trap: subtracting before squaring, e.g. (5−4)² = 1." },
  { id: "t21m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 8 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["2/3", "8/12", "1/2", "3/4"], correct: 0, explanation: "Goal: write and simplify the fraction. The team won 8 of 12, so 8/12, which reduces by dividing top and bottom by 4 to 2/3. Check: 2/3 of 12 is 8. Trap: leaving the fraction unsimplified as 8/12." },
  { id: "t21m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 6 = 14, what is the value of x?", type: "grid", gridAnswers: ["20"], explanation: "Goal: isolate x. Add 6 to both sides: x = 14 + 6 = 20. Check: 20 − 6 = 14. Trap: subtracting 6 instead of adding it." },
  { id: "t21m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 18, and 24?", type: "mcq", choices: ["18", "24", "16", "54"], correct: 0, explanation: "Goal: compute the mean. Add the values: 12 + 18 + 24 = 54, then divide by 3: 54 ÷ 3 = 18. Check: 18 is the middle value of three evenly spaced numbers. Trap: forgetting to divide and answering 54." },
  { id: "t21m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 9. What is its perimeter?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the perimeter of a square. Multiply the side by 4: 4 × 9 = 36. Check: all four equal sides of 9 sum to 36. Trap: computing area 9 × 9 = 81 instead of perimeter." },
  { id: "t21m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 3 = 17, what is the value of x?", type: "mcq", choices: ["7", "8", "10", "6"], correct: 0, explanation: "Goal: solve for x. Subtract 3: 2x = 14. Divide by 2: x = 7. Check: 2(7) + 3 = 14 + 3 = 17. Trap: dividing 17 by 2 before subtracting 3." },
  { id: "t21m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 8, what is f(6)?", type: "grid", gridAnswers: ["14"], explanation: "Goal: evaluate the function at x = 6. Substitute: f(6) = 6 + 8 = 14. Check: subtracting 8 from 14 returns the input 6. Trap: multiplying instead of adding." },
  { id: "t21m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 notebooks for $10. How much do 8 notebooks cost?", type: "mcq", choices: ["$16", "$13", "$18", "$15"], correct: 0, explanation: "Goal: find the unit price, then scale. Each notebook is $10 ÷ 5 = $2, so 8 notebooks cost 8 × $2 = $16. Check: 5 notebooks at $2 is the given $10. Trap: adding $3 for three extra notebooks at the wrong rate." },
  { id: "t21m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 54, what is the value of x?", type: "mcq", choices: ["9", "8", "6", "48"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 6: x = 54 ÷ 6 = 9. Check: 6 × 9 = 54. Trap: subtracting 6 from 54 instead of dividing." },
  { id: "t21m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 12 and a height of 5. What is its area?", type: "grid", gridAnswers: ["30"], explanation: "Goal: find triangle area. Use A = (1/2)(base)(height) = (1/2)(12)(5) = (1/2)(60) = 30. Check: a triangle is half the 12-by-5 rectangle of area 60. Trap: forgetting the 1/2 and answering 60." },
  { id: "t21m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 64?", type: "mcq", choices: ["16", "32", "8", "24"], correct: 0, explanation: "Goal: take 25% of a number. Note 25% is one quarter, so 64 ÷ 4 = 16. Check: four 16s make 64. Trap: halving instead of quartering, giving 32." },
  { id: "t21m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "grid", gridAnswers: ["21"], explanation: "Goal: solve for x. Multiply both sides by 3: x = 7 × 3 = 21. Check: 21 ÷ 3 = 7. Trap: dividing by 3 instead of multiplying." },
  { id: "t21m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "6", "12"], correct: 0, explanation: "Goal: evaluate a power. 3³ means 3 × 3 × 3 = 27. Check: 3² is 9, and one more factor of 3 gives 27. Trap: multiplying 3 by 3 only, giving 9." },
  { id: "t21m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 150 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["50", "45", "60", "30"], correct: 0, explanation: "Goal: find speed as distance over time. Divide: 150 ÷ 3 = 50 mph. Check: 50 mph for 3 hours covers 150 miles. Trap: multiplying 150 by 3 instead of dividing." },
  { id: "t21m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 5 = 11, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve for x. Add 5: 4x = 16. Divide by 4: x = 4. Check: 4(4) − 5 = 16 − 5 = 11. Trap: dividing 11 by 4 before adding 5." },
  { id: "t21m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a radius of 8. What is its diameter?", type: "mcq", choices: ["16", "8", "4", "64"], correct: 0, explanation: "Goal: find the diameter from the radius. The diameter is twice the radius: 2 × 8 = 16. Check: half of 16 is the radius 8. Trap: halving the radius instead of doubling it." },
  { id: "t21m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "2", "5"], correct: 0, explanation: "Goal: substitute and compute. Replace x with 5: y = 3 × 5 = 15. Check: dividing 15 by 3 returns x = 5. Trap: adding 3 and 5 to get 8." },
  { id: "t21m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A box holds 9 green and 6 red balls. What fraction of the balls are red?", type: "mcq", choices: ["2/5", "6/9", "1/2", "3/5"], correct: 0, explanation: "Goal: write the fraction of red balls. There are 6 red out of 9 + 6 = 15 total, so 6/15, which reduces by 3 to 2/5. Check: 2/5 of 15 is 6. Trap: using 6/9 by dividing red by green instead of by the total." },
];

// ─────────────────────── PRACTICE TEST 21 · MATH M2 hard (22) ────────────────
const T21_M_M2H: SatQuestion[] = [
  { id: "t21m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for the positive root. Add 64: x² = 64. Take the square root: x = ±8, and since x > 0, x = 8. Check: 8² − 64 = 64 − 64 = 0. Trap: reporting the negative root −8 despite the x > 0 condition." },
  { id: "t21m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 3y = 27 and x − 3y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "9"], correct: 0, explanation: "Goal: eliminate y by adding the equations. Adding gives 5x = 30, so x = 6. Check: with x = 6, 4(6) + 3y = 27 gives 3y = 3, y = 1, and 6 − 3(1) = 3 holds. Trap: subtracting the equations and losing the y-elimination." },
  { id: "t21m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve an exponential equation. Write 64 as a power of 2: 64 = 2⁶, so x = 6. Check: 2⁶ = 64. Trap: dividing 64 by 2 to get 32 instead of equating exponents." },
  { id: "t21m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $120 is marked up by 15%. What is the new price?", type: "mcq", choices: ["$138", "$135", "$144", "$105"], correct: 0, explanation: "Goal: add a 15% markup. Find 15% of 120: 0.15 × 120 = 18, then 120 + 18 = $138. Check: $138 is 1.15 × 120. Trap: subtracting 18 as if it were a discount, giving $102." },
  { id: "t21m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 8 and 15. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["17"], explanation: "Goal: apply the Pythagorean theorem. The hypotenuse is √(8² + 15²) = √(64 + 225) = √289 = 17. Check: 8-15-17 is a known Pythagorean triple. Trap: adding the legs 8 + 15 = 23 instead of using squares." },
  { id: "t21m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(3))?", type: "mcq", choices: ["19", "7", "21", "9"], correct: 0, explanation: "Goal: apply the function twice. First p(3) = 3(3) − 2 = 7, then p(7) = 3(7) − 2 = 21 − 2 = 19. Check: the inner value 7 feeds the outer function. Trap: stopping at the inner result 7 instead of composing." },
  { id: "t21m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 2y = 14 and x = y + 2, what is the value of y?", type: "grid", gridAnswers: ["1.6", "8/5"], explanation: "Goal: substitute and solve. Replace x: 3(y + 2) + 2y = 14, so 5y + 6 = 14, giving 5y = 8 and y = 8/5 = 1.6. Check: x = y + 2 = 3.6, and 3(3.6) + 2(1.6) = 10.8 + 3.2 = 14. Trap: dropping the distributed 3·2 = 6 term." },
  { id: "t21m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 11 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the x-coordinate of the vertex. Use h = −b/(2a) with a = 1, b = −8: h = −(−8)/(2·1) = 8/2 = 4. Check: the axis of symmetry is x = 4. Trap: forgetting the negative sign and getting −4." },
  { id: "t21m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 8/17. What is sin θ?", type: "mcq", choices: ["15/17", "8/15", "17/15", "15/8"], correct: 0, explanation: "Goal: find the missing side ratio. With adjacent 8 and hypotenuse 17, the opposite is √(17² − 8²) = √(289 − 64) = √225 = 15, so sin θ = 15/17. Check: 8-15-17 is a Pythagorean triple. Trap: using 15/8, the tangent, instead of sine." },
  { id: "t21m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: match a perfect square form. A perfect square x² + bx + 25 = (x + 5)² = x² + 10x + 25, so b = 10. Check: the constant 25 is 5², and the middle term is 2·5 = 10. Trap: setting b = 25 by confusing it with the constant." },
  { id: "t21m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−3", "5", "8"], correct: 0, explanation: "Goal: find b in y = mx + b. Substitute the point: 5 = −3(2) + b, so 5 = −6 + b and b = 11. Check: the line y = −3x + 11 passes through (2, 5). Trap: dropping the negative sign and computing 5 = 6 + b → b = −1." },
  { id: "t21m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a tablet costs $300. What was the original price?", type: "mcq", choices: ["$400", "$375", "$360", "$325"], correct: 0, explanation: "Goal: reverse a discount. Paying 25% less means $300 is 75% of the original, so original = 300 ÷ 0.75 = $400. Check: 25% of 400 is 100, and 400 − 100 = 300. Trap: adding 25% of 300 (which uses the wrong base) to get $375." },
  { id: "t21m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 49 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-7"], explanation: "Goal: solve a² = 49 under a sign condition. The square roots are ±7, and since a < 0, a = −7. Check: (−7)² = 49. Trap: reporting the positive root 7 despite a < 0." },
  { id: "t21m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: find cylinder volume. Use V = πr²h = π(4²)(6) = π(16)(6) = 96π. Check: square the radius first, then multiply by the height. Trap: using r instead of r², giving 24π." },
  { id: "t21m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["1.333", "4/3"], explanation: "Goal: solve for x. Subtract: 1/x = 1 − 1/4 = 3/4, so x = 4/3 ≈ 1.333. Check: 1/(4/3) + 1/4 = 3/4 + 1/4 = 1. Trap: forgetting to invert 3/4 and answering 3/4 for x." },
  { id: "t21m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "3"], correct: 0, explanation: "Goal: find the product of the roots. Factor: (x − 2)(x − 5) = 0, so the roots are 2 and 5 and their product is 10, which also equals c/a = 10/1. Check: both methods agree. Trap: using −7 (the sum-related term) as the product." },
  { id: "t21m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of red to blue tiles in a box is 2:7. If there are 45 tiles total, how many are blue?", type: "mcq", choices: ["35", "10", "30", "15"], correct: 0, explanation: "Goal: split a total by a ratio. The parts total 2 + 7 = 9, so each part is 45 ÷ 9 = 5; blue is 7 parts, 7 × 5 = 35. Check: red is 2 × 5 = 10, and 10 + 35 = 45. Trap: assigning blue the smaller share of 10." },
  { id: "t21m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 3, what is the area of the larger?", type: "grid", gridAnswers: ["48"], explanation: "Goal: scale area by the square of the linear ratio. Area scales by 4² = 16, so the larger area is 3 × 16 = 48. Check: linear ratio 4 squared is 16, the area ratio. Trap: scaling area by 4 instead of 16, giving 12." },
  { id: "t21m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: solve a radical equation. Square both sides: x + 5 = 36. Subtract 5: x = 31. Check: √(31 + 5) = √36 = 6. Trap: forgetting to square and subtracting 5 from 6 to get 1." },
  { id: "t21m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 2y = 24 and y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "7"], correct: 0, explanation: "Goal: substitute and solve. Replace y: 5x − 2(3) = 24, so 5x − 6 = 24. Add 6: 5x = 30, x = 6. Check: 5(6) − 6 = 30 − 6 = 24. Trap: forgetting to multiply 2 by 3 and using just −2." },
  { id: "t21m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 10x + 25, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve the quadratic. Recognize the perfect square: g(x) = (x − 5)², which equals 0 only when x = 5. Check: (5 − 5)² = 0. Trap: expecting two distinct roots when the double root is a single value, 5." },
  { id: "t21m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A colony of bacteria triples every hour. If it starts at 20, how many are there after 3 hours?", type: "mcq", choices: ["540", "180", "60", "1620"], correct: 0, explanation: "Goal: apply exponential growth. After 3 hours the count is 20 × 3³ = 20 × 27 = 540. Check: 20 → 60 → 180 → 540 over three hours. Trap: multiplying by 3 only once (giving 60) instead of three times." },
];

